package com.hasbreo.still;
import android.app.*;import android.os.*;import android.webkit.*;import android.widget.*;
public class AccessActivity extends Activity {protected void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);Button done=new Button(this);done.setText("Done — return to Still");done.setOnClickListener(v->{CookieManager.getInstance().flush();finish();});l.addView(done);WebView w=new WebView(this);w.getSettings().setJavaScriptEnabled(true);w.getSettings().setDomStorageEnabled(true);w.setWebViewClient(new WebViewClient());l.addView(w,new LinearLayout.LayoutParams(-1,0,1));setContentView(l);String url=getIntent().getStringExtra("url");if(url!=null&&url.startsWith("https://"))w.loadUrl(url);}}
